-- Move the JED3 categories over. asset_id is reset to 0 because the legacy #__assets rows are not migrated, and
-- the NOT NULL datetime columns get a substitute value where JED3 held a zero date.
DELETE FROM #__categories WHERE extension = 'com_jed';
INSERT INTO #__categories (id, asset_id, parent_id, lft, rgt, level, path, extension, title, alias, note, description, published, checked_out, checked_out_time, access, params, metadesc, metakey, metadata, created_user_id, created_time, modified_user_id, modified_time, hits, language, version) SELECT id, 0, parent_id, lft, rgt, level, LEFT(path, 400), extension, LEFT(title, 255), LEFT(alias, 400), LEFT(IFNULL(note, ''), 255), description, published, NULL, NULLIF(checked_out_time, '0000-00-00 00:00:00'), access, params, LEFT(IFNULL(metadesc, ''), 1024), LEFT(IFNULL(metakey, ''), 1024), LEFT(IFNULL(metadata, ''), 2048), created_user_id, IFNULL(NULLIF(created_time, '0000-00-00 00:00:00'), '2000-01-01 00:00:00'), modified_user_id, IFNULL(NULLIF(modified_time, '0000-00-00 00:00:00'), '2000-01-01 00:00:00'), hits, language, version FROM wqyh6_categories WHERE extension = 'com_jed';
